import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_21_intrinsic_extrinsic.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_21_icm_architecture.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_21_noisy_tv.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_21_rnd_mechanism.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_21_driving_boundary.png",f=JSON.parse('{"title":"越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱","description":"稀疏奖励任务里，环境很久才告诉智能体一次“成功”或“失败”。Intrinsic Motivation（内在动机）的思路是：即使没有外部奖励，也让智能体因为新颖、难预测或尚未掌握的状态获得额外反馈。这样它不必完全等待偶然成功，而会主动扩大经验覆盖。Curiosity（好奇心）是其中最直观的一类机制，但","frontmatter":{"title":"越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱","description":"稀疏奖励任务里，环境很久才告诉智能体一次“成功”或“失败”。Intrinsic Motivation（内在动机）的思路是：即使没有外部奖励，也让智能体因为新颖、难预测或尚未掌握的状态获得额外反馈。这样它不必完全等待偶然成功，而会主动扩大经验覆盖。Curiosity（好奇心）是其中最直观的一类机制，但","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":13,"source":"2026-08-13/rl_series_21_intrinsic_curiosity_icm.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_21_intrinsic_extrinsic.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-21-intrinsic-curiosity-icm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱"}],["meta",{"property":"og:description","content":"稀疏奖励任务里，环境很久才告诉智能体一次“成功”或“失败”。Intrinsic Motivation（内在动机）的思路是：即使没有外部奖励，也让智能体因为新颖、难预测或尚未掌握的状态获得额外反馈。这样它不必完全等待偶然成功，而会主动扩大经验覆盖。Curiosity（好奇心）是其中最直观的一类机制，但"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-21-intrinsic-curiosity-icm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_21_intrinsic_extrinsic.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱"}],["meta",{"name":"twitter:description","content":"稀疏奖励任务里，环境很久才告诉智能体一次“成功”或“失败”。Intrinsic Motivation（内在动机）的思路是：即使没有外部奖励，也让智能体因为新颖、难预测或尚未掌握的状态获得额外反馈。这样它不必完全等待偶然成功，而会主动扩大经验覆盖。Curiosity（好奇心）是其中最直观的一类机制，但"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_21_intrinsic_extrinsic.png"}]],"prev":{"text":"奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了","link":"/rl/rl-series-20-sparse-reward-shaping"},"next":{"text":"任务太难学不会？课程学习如何把成功区域一步步推远","link":"/rl/rl-series-22-curriculum-learning"}},"headers":[],"relativePath":"rl/rl-series-21-intrinsic-curiosity-icm.md","filePath":"rl/rl-series-21-intrinsic-curiosity-icm.md","lastUpdated":null}'),d={name:"rl/rl-series-21-intrinsic-curiosity-icm.md"};function c(p,a,_,u,b,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="越意外越值得探索吗-icm、rnd-与-噪声电视-陷阱" tabindex="-1">越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱 <a class="header-anchor" href="#越意外越值得探索吗-icm、rnd-与-噪声电视-陷阱" aria-label="Permalink to &quot;越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱&quot;">​</a></h1><p>稀疏奖励任务里，环境很久才告诉智能体一次“成功”或“失败”。Intrinsic Motivation（内在动机）的思路是：即使没有外部奖励，也让智能体因为新颖、难预测或尚未掌握的状态获得额外反馈。这样它不必完全等待偶然成功，而会主动扩大经验覆盖。Curiosity（好奇心）是其中最直观的一类机制，但“让我意外”与“对任务有用”从来不是同一件事。</p><p>Intrinsic Curiosity Module（内在好奇心模块，ICM）使用动作条件的特征预测误差作为内在奖励，并用 Inverse Dynamics（逆动力学）任务学习更关注可控变化的表示；Random Network Distillation（随机网络蒸馏，RND）则用预测固定随机目标网络的误差近似状态新颖性。两者都能改善 Hard Exploration（困难探索），也都会受到非平稳奖励、随机观测、尺度失衡和安全边界的影响。本篇把模块、梯度、归一化、陷阱与评价协议完整拆开。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-内在奖励用于改变探索分布" tabindex="-1">1.1 内在奖励用于改变探索分布 <a class="header-anchor" href="#_1-1-内在奖励用于改变探索分布" aria-label="Permalink to &quot;1.1 内在奖励用于改变探索分布&quot;">​</a></h3><p>外部奖励描述任务目标，内在奖励鼓励智能体访问新颖或难预测状态。二者相加后共同决定训练策略，但评估任务性能仍应回到外部目标。</p><h3 id="_1-2-icm-奖励可控特征中的预测误差" tabindex="-1">1.2 ICM 奖励可控特征中的预测误差 <a class="header-anchor" href="#_1-2-icm-奖励可控特征中的预测误差" aria-label="Permalink to &quot;1.2 ICM 奖励可控特征中的预测误差&quot;">​</a></h3><p>ICM 不直接预测原始像素，而是在自监督学习的特征空间预测下一状态。逆动力学分支促使特征保留与智能体动作相关的信息。</p><h3 id="_1-3-rnd-奖励对固定随机表示的预测误差" tabindex="-1">1.3 RND 奖励对固定随机表示的预测误差 <a class="header-anchor" href="#_1-3-rnd-奖励对固定随机表示的预测误差" aria-label="Permalink to &quot;1.3 RND 奖励对固定随机表示的预测误差&quot;">​</a></h3><p>目标网络随机初始化后固定，预测网络只在访问过的观测上训练。熟悉状态误差通常下降，新状态误差较大，因此可形成新颖性奖励。</p><h3 id="_1-4-高预测误差不代表高任务价值" tabindex="-1">1.4 高预测误差不代表高任务价值 <a class="header-anchor" href="#_1-4-高预测误差不代表高任务价值" aria-label="Permalink to &quot;1.4 高预测误差不代表高任务价值&quot;">​</a></h3><p>随机电视、传感器噪声、其他交通参与者和不可控扰动都可能持续难预测。智能体可能沉迷惊讶而忽略任务，甚至主动接近危险随机源。</p><p><img src="'+h+'" alt="外部任务奖励与内在探索奖励的关系"></p><h2 id="二、为什么普通随机探索不够" tabindex="-1">二、为什么普通随机探索不够 <a class="header-anchor" href="#二、为什么普通随机探索不够" aria-label="Permalink to &quot;二、为什么普通随机探索不够&quot;">​</a></h2><h3 id="_2-1-无方向噪声只能局部扰动动作" tabindex="-1">2.1 无方向噪声只能局部扰动动作 <a class="header-anchor" href="#_2-1-无方向噪声只能局部扰动动作" aria-label="Permalink to &quot;2.1 无方向噪声只能局部扰动动作&quot;">​</a></h3><p>(\\epsilon)-greedy（(\\epsilon)-贪心）或连续动作高斯噪声能让动作变化，却不会记住哪些区域已经访问、哪些区域仍然未知。</p><h3 id="_2-2-长时域目标需要一致探索行为" tabindex="-1">2.2 长时域目标需要一致探索行为 <a class="header-anchor" href="#_2-2-长时域目标需要一致探索行为" aria-label="Permalink to &quot;2.2 长时域目标需要一致探索行为&quot;">​</a></h3><p>穿过多个房间、完成多阶段装配或处理复杂交互，需要连续一段有方向的行为。逐步独立随机很难形成这样的轨迹。</p><h3 id="_2-3-访问计数在高维观测中难以直接使用" tabindex="-1">2.3 访问计数在高维观测中难以直接使用 <a class="header-anchor" href="#_2-3-访问计数在高维观测中难以直接使用" aria-label="Permalink to &quot;2.3 访问计数在高维观测中难以直接使用&quot;">​</a></h3><p>表格状态可按访问次数给奖励，高维图像几乎每帧都不同。需要用特征、密度或预测误差定义“相似状态是否见过”。</p><h3 id="_2-4-探索奖励也需要逐渐衰减" tabindex="-1">2.4 探索奖励也需要逐渐衰减 <a class="header-anchor" href="#_2-4-探索奖励也需要逐渐衰减" aria-label="Permalink to &quot;2.4 探索奖励也需要逐渐衰减&quot;">​</a></h3><p>同一状态反复访问后应变得熟悉，否则智能体会永久循环。预测模型学习使误差下降，正好提供一种自适应衰减机制。</p><h2 id="三、icm-的三个模块分别做什么" tabindex="-1">三、ICM 的三个模块分别做什么 <a class="header-anchor" href="#三、icm-的三个模块分别做什么" aria-label="Permalink to &quot;三、ICM 的三个模块分别做什么&quot;">​</a></h2><h3 id="_3-1-特征编码器压缩观测" tabindex="-1">3.1 特征编码器压缩观测 <a class="header-anchor" href="#_3-1-特征编码器压缩观测" aria-label="Permalink to &quot;3.1 特征编码器压缩观测&quot;">​</a></h3><p>编码器 (\\phi(s)) 将图像或状态向量映射到特征空间。内在奖励在特征上计算，避免逐像素预测无关细节。</p><h3 id="_3-2-逆动力学模型预测已执行动作" tabindex="-1">3.2 逆动力学模型预测已执行动作 <a class="header-anchor" href="#_3-2-逆动力学模型预测已执行动作" aria-label="Permalink to &quot;3.2 逆动力学模型预测已执行动作&quot;">​</a></h3><p>逆模型接收 (\\phi(s_t)) 和 (\\phi(s_{t+1}))，预测把前一状态变成后一状态的动作 (a_t)。</p><h3 id="_3-3-前向动力学模型预测下一特征" tabindex="-1">3.3 前向动力学模型预测下一特征 <a class="header-anchor" href="#_3-3-前向动力学模型预测下一特征" aria-label="Permalink to &quot;3.3 前向动力学模型预测下一特征&quot;">​</a></h3><p>前向模型接收 (\\phi(s_t)) 与 (a_t)，输出预测特征 (\\hat\\phi(s_{t+1}))。</p><h3 id="_3-4-策略使用预测误差作为奖励" tabindex="-1">3.4 策略使用预测误差作为奖励 <a class="header-anchor" href="#_3-4-策略使用预测误差作为奖励" aria-label="Permalink to &quot;3.4 策略使用预测误差作为奖励&quot;">​</a></h3><p>预测越不准确，说明转移对当前模型越陌生，智能体获得的内在奖励越高。</p><p><img src="'+o+'" alt="ICM 的编码器、逆模型与前向模型"></p><h2 id="四、icm-的损失和奖励怎样计算" tabindex="-1">四、ICM 的损失和奖励怎样计算 <a class="header-anchor" href="#四、icm-的损失和奖励怎样计算" aria-label="Permalink to &quot;四、ICM 的损失和奖励怎样计算&quot;">​</a></h2><h3 id="_4-1-逆模型损失学习动作相关表示" tabindex="-1">4.1 逆模型损失学习动作相关表示 <a class="header-anchor" href="#_4-1-逆模型损失学习动作相关表示" aria-label="Permalink to &quot;4.1 逆模型损失学习动作相关表示&quot;">​</a></h3><p>离散动作可使用 Cross-Entropy Loss（交叉熵损失），连续动作可使用回归损失。记为：</p><p>$$ L_{inv}=\\ell\\left(\\hat a_t,a_t\\right) $$</p><h3 id="_4-2-前向模型损失衡量特征预测" tabindex="-1">4.2 前向模型损失衡量特征预测 <a class="header-anchor" href="#_4-2-前向模型损失衡量特征预测" aria-label="Permalink to &quot;4.2 前向模型损失衡量特征预测&quot;">​</a></h3><p>$$ L_{fwd}=\\frac{1}{2}\\left|\\hat\\phi(s_{t+1})-\\phi(s_{t+1})\\right|_2^2 $$</p><h3 id="_4-3-内在奖励取前向预测误差" tabindex="-1">4.3 内在奖励取前向预测误差 <a class="header-anchor" href="#_4-3-内在奖励取前向预测误差" aria-label="Permalink to &quot;4.3 内在奖励取前向预测误差&quot;">​</a></h3><p>$$ r_t^i=\\eta L_{fwd} $$</p><p>其中 (\\eta) 控制内在奖励尺度。策略通常优化：</p><p>$$ r_t^{train}=r_t^{ext}+\\beta r_t^i $$</p><h3 id="_4-4-总目标包含策略与好奇心模块" tabindex="-1">4.4 总目标包含策略与好奇心模块 <a class="header-anchor" href="#_4-4-总目标包含策略与好奇心模块" aria-label="Permalink to &quot;4.4 总目标包含策略与好奇心模块&quot;">​</a></h3><p>实现会联合或交替优化策略损失、逆模型损失和前向模型损失。不同分支是否向编码器回传梯度必须明确，否则表示学习目标会悄然变化。</p><h2 id="五、逆动力学为什么能过滤部分无关变化" tabindex="-1">五、逆动力学为什么能过滤部分无关变化 <a class="header-anchor" href="#五、逆动力学为什么能过滤部分无关变化" aria-label="Permalink to &quot;五、逆动力学为什么能过滤部分无关变化&quot;">​</a></h2><h3 id="_5-1-可控变化有助于预测动作" tabindex="-1">5.1 可控变化有助于预测动作 <a class="header-anchor" href="#_5-1-可控变化有助于预测动作" aria-label="Permalink to &quot;5.1 可控变化有助于预测动作&quot;">​</a></h3><p>智能体向左移动导致自身位置变化，这类特征能帮助逆模型识别动作，应被编码器保留。</p><h3 id="_5-2-不受动作控制的背景价值较低" tabindex="-1">5.2 不受动作控制的背景价值较低 <a class="header-anchor" href="#_5-2-不受动作控制的背景价值较低" aria-label="Permalink to &quot;5.2 不受动作控制的背景价值较低&quot;">​</a></h3><p>云层、树叶或纹理闪烁若与动作无关，对预测 (a_t) 帮助小，理想情况下不会成为主要特征。</p><h3 id="_5-3-过滤能力不是严格保证" tabindex="-1">5.3 过滤能力不是严格保证 <a class="header-anchor" href="#_5-3-过滤能力不是严格保证" aria-label="Permalink to &quot;5.3 过滤能力不是严格保证&quot;">​</a></h3><p>网络可能仍编码背景相关性，尤其当数据偏差让动作与背景变化偶然相关。逆动力学只提供学习压力，不是因果可控性的证明。</p><h3 id="_5-4-动作不可辨识时表示也会受限" tabindex="-1">5.4 动作不可辨识时表示也会受限 <a class="header-anchor" href="#_5-4-动作不可辨识时表示也会受限" aria-label="Permalink to &quot;5.4 动作不可辨识时表示也会受限&quot;">​</a></h3><p>多个动作可能产生相似状态变化，或观测不足以辨别动作。此时逆模型目标本身含糊，不能期待特征完美分离可控因素。</p><h2 id="六、-噪声电视-问题从哪里来" tabindex="-1">六、“噪声电视”问题从哪里来 <a class="header-anchor" href="#六、-噪声电视-问题从哪里来" aria-label="Permalink to &quot;六、“噪声电视”问题从哪里来&quot;">​</a></h2><h3 id="_6-1-随机观测始终难以预测" tabindex="-1">6.1 随机观测始终难以预测 <a class="header-anchor" href="#_6-1-随机观测始终难以预测" aria-label="Permalink to &quot;6.1 随机观测始终难以预测&quot;">​</a></h3><p>若环境里有播放随机图像的电视，下一帧即使访问无数次仍不可预测，前向误差不会随熟悉度充分下降。</p><h3 id="_6-2-智能体会优化可持续获得的惊讶" tabindex="-1">6.2 智能体会优化可持续获得的惊讶 <a class="header-anchor" href="#_6-2-智能体会优化可持续获得的惊讶" aria-label="Permalink to &quot;6.2 智能体会优化可持续获得的惊讶&quot;">​</a></h3><p>只要内在奖励足够大，策略就可能停在电视前反复观看，而不是寻找外部目标。这就是经典 Noisy TV Problem（噪声电视问题）。</p><h3 id="_6-3-随机性不等于知识空缺" tabindex="-1">6.3 随机性不等于知识空缺 <a class="header-anchor" href="#_6-3-随机性不等于知识空缺" aria-label="Permalink to &quot;6.3 随机性不等于知识空缺&quot;">​</a></h3><p>Epistemic Uncertainty（认知不确定性）可随数据增加而下降，Aleatoric Uncertainty（偶然不确定性）来自环境固有随机性。单纯预测误差会混合二者。</p><h3 id="_6-4-自动驾驶中随机源更加普遍" tabindex="-1">6.4 自动驾驶中随机源更加普遍 <a class="header-anchor" href="#_6-4-自动驾驶中随机源更加普遍" aria-label="Permalink to &quot;6.4 自动驾驶中随机源更加普遍&quot;">​</a></h3><p>遮挡行人、传感器噪声、光照闪烁和其他车辆行为都可能产生高误差。鼓励接近它们可能与安全目标相反。</p><p><img src="'+l+'" alt="预测误差机制可能被随机噪声持续吸引"></p><h2 id="七、rnd-怎样定义状态新颖性" tabindex="-1">七、RND 怎样定义状态新颖性 <a class="header-anchor" href="#七、rnd-怎样定义状态新颖性" aria-label="Permalink to &quot;七、RND 怎样定义状态新颖性&quot;">​</a></h2><h3 id="_7-1-固定一个随机目标网络" tabindex="-1">7.1 固定一个随机目标网络 <a class="header-anchor" href="#_7-1-固定一个随机目标网络" aria-label="Permalink to &quot;7.1 固定一个随机目标网络&quot;">​</a></h3><p>目标网络 (f_{target}(s)) 随机初始化后不再更新，为每个观测生成固定特征目标。</p><h3 id="_7-2-训练预测网络逼近随机特征" tabindex="-1">7.2 训练预测网络逼近随机特征 <a class="header-anchor" href="#_7-2-训练预测网络逼近随机特征" aria-label="Permalink to &quot;7.2 训练预测网络逼近随机特征&quot;">​</a></h3><p>预测网络 (f_{pred}(s)) 在访问到的观测上最小化：</p><p>$$ L_{RND}=\\left|f_{pred}(s)-f_{target}(s)\\right|_2^2 $$</p><h3 id="_7-3-预测误差成为内在奖励" tabindex="-1">7.3 预测误差成为内在奖励 <a class="header-anchor" href="#_7-3-预测误差成为内在奖励" aria-label="Permalink to &quot;7.3 预测误差成为内在奖励&quot;">​</a></h3><p>熟悉观测被训练多次后误差降低，新观测通常误差较大，因此：</p><p>$$ r^i(s)=\\eta\\left|f_{pred}(s)-f_{target}(s)\\right|_2^2 $$</p><h3 id="_7-4-rnd-不需要学习环境动力学" tabindex="-1">7.4 RND 不需要学习环境动力学 <a class="header-anchor" href="#_7-4-rnd-不需要学习环境动力学" aria-label="Permalink to &quot;7.4 RND 不需要学习环境动力学&quot;">​</a></h3><p>它只看单个观测，不输入动作，也不预测下一状态，结构比 ICM 简单；代价是无法借助逆动力学明确强调动作可控因素。</p><p><img src="'+n+'" alt="RND 用固定随机目标与可训练预测器计算新颖性"></p><h2 id="八、icm-与-rnd-有什么核心差异" tabindex="-1">八、ICM 与 RND 有什么核心差异 <a class="header-anchor" href="#八、icm-与-rnd-有什么核心差异" aria-label="Permalink to &quot;八、ICM 与 RND 有什么核心差异&quot;">​</a></h2><h3 id="_8-1-奖励对象不同" tabindex="-1">8.1 奖励对象不同 <a class="header-anchor" href="#_8-1-奖励对象不同" aria-label="Permalink to &quot;8.1 奖励对象不同&quot;">​</a></h3><p>ICM 奖励动作条件的下一特征预测误差，关注转移；RND 奖励当前观测随机表示的预测误差，更接近访问新颖性。</p><h3 id="_8-2-表示来源不同" tabindex="-1">8.2 表示来源不同 <a class="header-anchor" href="#_8-2-表示来源不同" aria-label="Permalink to &quot;8.2 表示来源不同&quot;">​</a></h3><p>ICM 的表示由逆动力学自监督学习；RND 的目标表示固定随机，预测器通过访问数据学习逼近。</p><h3 id="_8-3-对环境随机性的反应不同" tabindex="-1">8.3 对环境随机性的反应不同 <a class="header-anchor" href="#_8-3-对环境随机性的反应不同" aria-label="Permalink to &quot;8.3 对环境随机性的反应不同&quot;">​</a></h3><p>ICM 可能被随机转移持续吸引，RND 若每次随机观测都不同也会保持高误差。两者都没有从根本上消除噪声电视。</p><h3 id="_8-4-计算和工程复杂度不同" tabindex="-1">8.4 计算和工程复杂度不同 <a class="header-anchor" href="#_8-4-计算和工程复杂度不同" aria-label="Permalink to &quot;8.4 计算和工程复杂度不同&quot;">​</a></h3><p>ICM 包含编码器、前向与逆向模型，并依赖转移和动作；RND 只需两个观测编码网络，但仍要处理归一化、优化和非平稳奖励。</p><h3 id="_8-5-没有方法在所有任务上占优" tabindex="-1">8.5 没有方法在所有任务上占优 <a class="header-anchor" href="#_8-5-没有方法在所有任务上占优" aria-label="Permalink to &quot;8.5 没有方法在所有任务上占优&quot;">​</a></h3><p>方法选择应由观测类型、环境随机性、动作可控性和任务跨度决定，不能只依据某个基准游戏的最高分。</p><h2 id="九、内在奖励为什么是非平稳的" tabindex="-1">九、内在奖励为什么是非平稳的 <a class="header-anchor" href="#九、内在奖励为什么是非平稳的" aria-label="Permalink to &quot;九、内在奖励为什么是非平稳的&quot;">​</a></h2><h3 id="_9-1-预测器持续学习会改变同一状态奖励" tabindex="-1">9.1 预测器持续学习会改变同一状态奖励 <a class="header-anchor" href="#_9-1-预测器持续学习会改变同一状态奖励" aria-label="Permalink to &quot;9.1 预测器持续学习会改变同一状态奖励&quot;">​</a></h3><p>同一转移在训练早期可能很新颖，后来误差下降。策略面对的奖励函数随时间变化，不再是固定 MDP 奖励。</p><h3 id="_9-2-回放旧转移时奖励可能需要重算" tabindex="-1">9.2 回放旧转移时奖励可能需要重算 <a class="header-anchor" href="#_9-2-回放旧转移时奖励可能需要重算" aria-label="Permalink to &quot;9.2 回放旧转移时奖励可能需要重算&quot;">​</a></h3><p>若缓冲区保存旧内在奖励，训练目标对应历史预测器；若在线重算，同一数据标签又会变化。两种方案都应明确并验证。</p><h3 id="_9-3-快慢学习率形成时间尺度耦合" tabindex="-1">9.3 快慢学习率形成时间尺度耦合 <a class="header-anchor" href="#_9-3-快慢学习率形成时间尺度耦合" aria-label="Permalink to &quot;9.3 快慢学习率形成时间尺度耦合&quot;">​</a></h3><p>预测器太快，内在奖励迅速消失；太慢，熟悉状态仍持续高奖励。策略学习率、预测器学习率和数据更新比共同决定行为。</p><h3 id="_9-4-训练曲线不能只看总奖励" tabindex="-1">9.4 训练曲线不能只看总奖励 <a class="header-anchor" href="#_9-4-训练曲线不能只看总奖励" aria-label="Permalink to &quot;9.4 训练曲线不能只看总奖励&quot;">​</a></h3><p>总训练奖励下降可能只是预测器变准，而非策略退化；上升也可能只是访问更多随机噪声。外部回报和探索覆盖必须分开记录。</p><h2 id="十、归一化为什么决定训练是否稳定" tabindex="-1">十、归一化为什么决定训练是否稳定 <a class="header-anchor" href="#十、归一化为什么决定训练是否稳定" aria-label="Permalink to &quot;十、归一化为什么决定训练是否稳定&quot;">​</a></h2><h3 id="_10-1-观测尺度影响预测难度" tabindex="-1">10.1 观测尺度影响预测难度 <a class="header-anchor" href="#_10-1-观测尺度影响预测难度" aria-label="Permalink to &quot;10.1 观测尺度影响预测难度&quot;">​</a></h3><p>像素范围、状态量纲和标准化统计会改变网络误差。训练与评估必须使用一致的预处理。</p><h3 id="_10-2-内在奖励需要运行统计量" tabindex="-1">10.2 内在奖励需要运行统计量 <a class="header-anchor" href="#_10-2-内在奖励需要运行统计量" aria-label="Permalink to &quot;10.2 内在奖励需要运行统计量&quot;">​</a></h3><p>常用 Running Mean and Variance（运行均值与方差）标准化预测误差，避免少数巨大值主导策略梯度。</p><h3 id="_10-3-外部与内在奖励尺度必须分开观察" tabindex="-1">10.3 外部与内在奖励尺度必须分开观察 <a class="header-anchor" href="#_10-3-外部与内在奖励尺度必须分开观察" aria-label="Permalink to &quot;10.3 外部与内在奖励尺度必须分开观察&quot;">​</a></h3><p>(\\beta) 只有结合两种奖励的实际分布才有意义。固定权重在训练不同阶段可能产生完全不同的相对影响。</p><h3 id="_10-4-奖励裁剪会丢失新颖性差异" tabindex="-1">10.4 奖励裁剪会丢失新颖性差异 <a class="header-anchor" href="#_10-4-奖励裁剪会丢失新颖性差异" aria-label="Permalink to &quot;10.4 奖励裁剪会丢失新颖性差异&quot;">​</a></h3><p>裁剪可以抑制异常值，也可能把“略新”和“极新”压成相同奖励。应报告裁剪阈值及裁剪比例。</p><h2 id="十一、如何判断探索真的改善了" tabindex="-1">十一、如何判断探索真的改善了 <a class="header-anchor" href="#十一、如何判断探索真的改善了" aria-label="Permalink to &quot;十一、如何判断探索真的改善了&quot;">​</a></h2><h3 id="_11-1-记录状态或房间覆盖率" tabindex="-1">11.1 记录状态或房间覆盖率 <a class="header-anchor" href="#_11-1-记录状态或房间覆盖率" aria-label="Permalink to &quot;11.1 记录状态或房间覆盖率&quot;">​</a></h3><p>可用离散位置、聚类特征、地图网格或任务阶段统计覆盖，而不是用内在奖励总和代替探索程度。</p><h3 id="_11-2-记录首次外部成功时间" tabindex="-1">11.2 记录首次外部成功时间 <a class="header-anchor" href="#_11-2-记录首次外部成功时间" aria-label="Permalink to &quot;11.2 记录首次外部成功时间&quot;">​</a></h3><p>首次成功环境步和多个种子的成功比例，能直接衡量内在奖励是否帮助发现目标。</p><h3 id="_11-3-关闭内在奖励进行确定性评估" tabindex="-1">11.3 关闭内在奖励进行确定性评估 <a class="header-anchor" href="#_11-3-关闭内在奖励进行确定性评估" aria-label="Permalink to &quot;11.3 关闭内在奖励进行确定性评估&quot;">​</a></h3><p>评估阶段按任务协议执行策略，不把内在奖励计入成绩。否则算法可能因“更惊讶”而看似更强。</p><h3 id="_11-4-检查策略是否停留在随机源附近" tabindex="-1">11.4 检查策略是否停留在随机源附近 <a class="header-anchor" href="#_11-4-检查策略是否停留在随机源附近" aria-label="Permalink to &quot;11.4 检查策略是否停留在随机源附近&quot;">​</a></h3><p>可视化访问热图、停留时间和失败轨迹，主动寻找噪声电视、边界抖动和重复循环。</p><h3 id="_11-5-比较相同环境步和计算预算" tabindex="-1">11.5 比较相同环境步和计算预算 <a class="header-anchor" href="#_11-5-比较相同环境步和计算预算" aria-label="Permalink to &quot;11.5 比较相同环境步和计算预算&quot;">​</a></h3><p>ICM 与 RND 引入额外网络和梯度更新。只对齐环境步而忽略计算成本，会高估工程收益。</p><h2 id="十二、自动驾驶中内在动机的边界" tabindex="-1">十二、自动驾驶中内在动机的边界 <a class="header-anchor" href="#十二、自动驾驶中内在动机的边界" aria-label="Permalink to &quot;十二、自动驾驶中内在动机的边界&quot;">​</a></h2><h3 id="_12-1-真实车辆不能自由执行危险探索" tabindex="-1">12.1 真实车辆不能自由执行危险探索 <a class="header-anchor" href="#_12-1-真实车辆不能自由执行危险探索" aria-label="Permalink to &quot;12.1 真实车辆不能自由执行危险探索&quot;">​</a></h3><p>随机或好奇驱动动作可能接近碰撞、越界和不稳定区域。训练探索应主要发生在仿真、受控测试场或有独立安全层的系统中。</p><h3 id="_12-2-新颖场景不等于应主动接近" tabindex="-1">12.2 新颖场景不等于应主动接近 <a class="header-anchor" href="#_12-2-新颖场景不等于应主动接近" aria-label="Permalink to &quot;12.2 新颖场景不等于应主动接近&quot;">​</a></h3><p>罕见障碍、异常车辆和传感器故障值得被数据系统覆盖，却不代表在线控制策略应靠近它们获取奖励。</p><h3 id="_12-3-数据采集与控制策略可分离" tabindex="-1">12.3 数据采集与控制策略可分离 <a class="header-anchor" href="#_12-3-数据采集与控制策略可分离" aria-label="Permalink to &quot;12.3 数据采集与控制策略可分离&quot;">​</a></h3><p>可以让场景生成器、仿真参数采样或测试调度器追求覆盖，而让车辆控制器仍以任务和安全约束为主。</p><h3 id="_12-4-安全介入会改变探索数据" tabindex="-1">12.4 安全介入会改变探索数据 <a class="header-anchor" href="#_12-4-安全介入会改变探索数据" aria-label="Permalink to &quot;12.4 安全介入会改变探索数据&quot;">​</a></h3><p>Shield（安全屏障）修改危险动作后，回放池必须记录策略提议动作、实际执行动作和介入原因，否则动力学模型与策略更新会产生语义错位。</p><h3 id="_12-5-内在奖励不提供安全证明" tabindex="-1">12.5 内在奖励不提供安全证明 <a class="header-anchor" href="#_12-5-内在奖励不提供安全证明" aria-label="Permalink to &quot;12.5 内在奖励不提供安全证明&quot;">​</a></h3><p>预测误差、访问新颖性和不确定性估计都不能替代碰撞约束、可达性分析、CBF（控制屏障函数）或备用控制器。</p><p><img src="'+s+'" alt="自动驾驶中探索模块与安全执行链应分层"></p><h2 id="十三、一个最小实验怎样设计" tabindex="-1">十三、一个最小实验怎样设计 <a class="header-anchor" href="#十三、一个最小实验怎样设计" aria-label="Permalink to &quot;十三、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_13-1-使用带无关随机源的稀疏导航" tabindex="-1">13.1 使用带无关随机源的稀疏导航 <a class="header-anchor" href="#_13-1-使用带无关随机源的稀疏导航" aria-label="Permalink to &quot;13.1 使用带无关随机源的稀疏导航&quot;">​</a></h3><p>构造目标稀疏奖励，同时在一处加入随机纹理或随机观测区域，让实验能够暴露噪声电视问题。</p><h3 id="_13-2-建立无内在奖励基线" tabindex="-1">13.2 建立无内在奖励基线 <a class="header-anchor" href="#_13-2-建立无内在奖励基线" aria-label="Permalink to &quot;13.2 建立无内在奖励基线&quot;">​</a></h3><p>使用相同 PPO（近端策略优化）或 DQN（深度 Q 网络）、环境步数、网络规模与随机种子，先记录普通探索覆盖。</p><h3 id="_13-3-分别加入-icm-和-rnd" tabindex="-1">13.3 分别加入 ICM 和 RND <a class="header-anchor" href="#_13-3-分别加入-icm-和-rnd" aria-label="Permalink to &quot;13.3 分别加入 ICM 和 RND&quot;">​</a></h3><p>记录外部回报、内在回报、预测损失、覆盖率、首次成功步数和随机区域停留比例。</p><h3 id="_13-4-做内在奖励权重消融" tabindex="-1">13.4 做内在奖励权重消融 <a class="header-anchor" href="#_13-4-做内在奖励权重消融" aria-label="Permalink to &quot;13.4 做内在奖励权重消融&quot;">​</a></h3><p>权重过低可能没有效果，过高可能忽略任务。至少比较多个数量级，并观察训练阶段的相对奖励尺度。</p><h3 id="_13-5-增加可控与不可控随机性对照" tabindex="-1">13.5 增加可控与不可控随机性对照 <a class="header-anchor" href="#_13-5-增加可控与不可控随机性对照" aria-label="Permalink to &quot;13.5 增加可控与不可控随机性对照&quot;">​</a></h3><p>可控机关能通过动作影响，不可控电视与动作无关。该对照可以检验表示是否真正聚焦可控变化。</p><h2 id="十四、最常见的实现错误" tabindex="-1">十四、最常见的实现错误 <a class="header-anchor" href="#十四、最常见的实现错误" aria-label="Permalink to &quot;十四、最常见的实现错误&quot;">​</a></h2><h3 id="_14-1-目标特征分支没有正确停止梯度" tabindex="-1">14.1 目标特征分支没有正确停止梯度 <a class="header-anchor" href="#_14-1-目标特征分支没有正确停止梯度" aria-label="Permalink to &quot;14.1 目标特征分支没有正确停止梯度&quot;">​</a></h3><p>若前向损失同时任意改变目标特征，编码器可能通过收缩表示降低误差，而不是学会预测动力学。</p><h3 id="_14-2-rnd-目标网络被优化器更新" tabindex="-1">14.2 RND 目标网络被优化器更新 <a class="header-anchor" href="#_14-2-rnd-目标网络被优化器更新" aria-label="Permalink to &quot;14.2 RND 目标网络被优化器更新&quot;">​</a></h3><p>目标网络必须固定。若它随预测器一起变化，误差不再具有稳定的新颖性参照。</p><h3 id="_14-3-把终止后的重置跳变当成新奇转移" tabindex="-1">14.3 把终止后的重置跳变当成新奇转移 <a class="header-anchor" href="#_14-3-把终止后的重置跳变当成新奇转移" aria-label="Permalink to &quot;14.3 把终止后的重置跳变当成新奇转移&quot;">​</a></h3><p>回合末状态到新初始状态不是环境内正常动力学，不能直接用于 ICM 前向预测。</p><h3 id="_14-4-没有规范化内在奖励" tabindex="-1">14.4 没有规范化内在奖励 <a class="header-anchor" href="#_14-4-没有规范化内在奖励" aria-label="Permalink to &quot;14.4 没有规范化内在奖励&quot;">​</a></h3><p>少量极端预测误差会主导优势估计，使策略更新突然失稳。</p><h3 id="_14-5-用训练总奖励宣称任务性能提升" tabindex="-1">14.5 用训练总奖励宣称任务性能提升 <a class="header-anchor" href="#_14-5-用训练总奖励宣称任务性能提升" aria-label="Permalink to &quot;14.5 用训练总奖励宣称任务性能提升&quot;">​</a></h3><p>加入内在奖励后，总奖励定义已经改变，不能与无内在奖励基线直接比较。</p><h2 id="十五、学到什么程度才算掌握" tabindex="-1">十五、学到什么程度才算掌握 <a class="header-anchor" href="#十五、学到什么程度才算掌握" aria-label="Permalink to &quot;十五、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_15-1-能画出-icm-的两条自监督路径" tabindex="-1">15.1 能画出 ICM 的两条自监督路径 <a class="header-anchor" href="#_15-1-能画出-icm-的两条自监督路径" aria-label="Permalink to &quot;15.1 能画出 ICM 的两条自监督路径&quot;">​</a></h3><p>你应能说明逆模型怎样学习动作相关特征，前向模型怎样产生内在奖励，以及各分支的梯度边界。</p><h3 id="_15-2-能写出-rnd-的固定目标机制" tabindex="-1">15.2 能写出 RND 的固定目标机制 <a class="header-anchor" href="#_15-2-能写出-rnd-的固定目标机制" aria-label="Permalink to &quot;15.2 能写出 RND 的固定目标机制&quot;">​</a></h3><p>你应能解释预测误差为何随访问下降，以及随机观测为何仍可能保持高误差。</p><h3 id="_15-3-能区分惊讶、新颖、价值与安全" tabindex="-1">15.3 能区分惊讶、新颖、价值与安全 <a class="header-anchor" href="#_15-3-能区分惊讶、新颖、价值与安全" aria-label="Permalink to &quot;15.3 能区分惊讶、新颖、价值与安全&quot;">​</a></h3><p>它们有时相关，但没有逻辑等价关系，必须使用不同指标和约束验证。</p><h3 id="_15-4-能设计噪声电视对照实验" tabindex="-1">15.4 能设计噪声电视对照实验 <a class="header-anchor" href="#_15-4-能设计噪声电视对照实验" aria-label="Permalink to &quot;15.4 能设计噪声电视对照实验&quot;">​</a></h3><p>一个完整实验必须主动包含不可控随机源，而不是只在确定性环境展示成功曲线。</p><h3 id="_15-5-能进入课程学习" tabindex="-1">15.5 能进入课程学习 <a class="header-anchor" href="#_15-5-能进入课程学习" aria-label="Permalink to &quot;15.5 能进入课程学习&quot;">​</a></h3><p>下一篇将从“改变奖励”转向“改变任务分布”，解释 Curriculum Learning（课程学习）和 Reverse Curriculum（逆向课程）如何让成功区域随能力逐步扩张。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter10/chapter10.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十章好奇心部分</a></p><p><a href="https://arxiv.org/abs/1705.05363" target="_blank" rel="noreferrer">Pathak 等《Curiosity-driven Exploration by Self-supervised Prediction》</a></p><p><a href="https://pathak22.github.io/noreward-rl/" target="_blank" rel="noreferrer">ICM 作者项目页与参考实现</a></p><p><a href="https://arxiv.org/abs/1810.12894" target="_blank" rel="noreferrer">Burda 等《Exploration by Random Network Distillation》</a></p><p><a href="https://openreview.net/forum?id=H1lJJnR5Ym" target="_blank" rel="noreferrer">ICLR 2019 RND 论文页面</a></p>',166)])])}const x=e(d,[["render",c]]);export{f as __pageData,x as default};
